type BackoffConfig struct {
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each failed retry.
	Multiplier float64
	// Jitter is the fraction of the backoff delay to randomize.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
	// MinConnectTimeout is the minimum time to give a connection attempt to complete.
	MinConnectTimeout time.Duration
}

type Exponential struct {
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each failed retry.
	Multiplier float64
	// Jitter is the fraction of the backoff delay to randomize.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

func (bc Exponential) Backoff(retries int) time.Duration {
	base := bc.BaseDelay
	if base <= 0 {
		base = baseDelay
	}
	if retries == 0 {
		return base
	}
	multiplier := bc.Multiplier
	if multiplier <= 0 {
		multiplier = factor
	}
	jitter := bc.Jitter
	if jitter <= 0 {
		jitter = 0.2
	}
	backoff, max := float64(base), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= multiplier
		retries--
	}
	if backoff > max {
		backoff = max
	}
	// Randomize backoff delays so that if a cluster of requests start at
	// the same time, they won't operate in lockstep.
	backoff *= 1 + jitter*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

func WithBackoffMaxDelay(md time.Duration) DialOption {
	config := DefaultBackoffConfig
	config.MaxDelay = md
	return WithBackoffConfig(config)
}

func WithBackoffConfig(b BackoffConfig) DialOption {
	minConnectTimeout := b.MinConnectTimeout
	if minConnectTimeout <= 0 {
		minConnectTimeout = DefaultBackoffConfig.MinConnectTimeout
	}
	return newFuncDialOption(func(o *dialOptions) {
		o.bs = backoff.Exponential{
			BaseDelay:  b.BaseDelay,
			Multiplier: b.Multiplier,
			Jitter:     b.Jitter,
			MaxDelay:   b.MaxDelay,
		}
		o.minConnectTimeout = func() time.Duration {
			return minConnectTimeout
		}
	})
}

if cc.dopts.bs == nil {
		cc.dopts.bs = backoff.Exponential{
			BaseDelay:  DefaultBackoffConfig.BaseDelay,
			Multiplier: DefaultBackoffConfig.Multiplier,
			Jitter:     DefaultBackoffConfig.Jitter,
			MaxDelay:   DefaultBackoffConfig.MaxDelay,
		}
	}
	if cc.dopts.minConnectTimeout == nil {
		cc.dopts.minConnectTimeout = func() time.Duration {
			return DefaultBackoffConfig.MinConnectTimeout
		}
	}

if cc.dopts.bs == nil {
		cc.dopts.bs = backoff.Exponential{
			BaseDelay:  DefaultBackoffConfig.BaseDelay,
			Multiplier: DefaultBackoffConfig.Multiplier,
			Jitter:     DefaultBackoffConfig.Jitter,
			MaxDelay:   DefaultBackoffConfig.MaxDelay,
		}
	}

if cc.dopts.bs == nil {
		cc.dopts.bs = backoff.Exponential{
			BaseDelay:  DefaultBackoffConfig.BaseDelay,
			Multiplier: DefaultBackoffConfig.Multiplier,
			Jitter:     DefaultBackoffConfig.Jitter,
			MaxDelay:   DefaultBackoffConfig.MaxDelay,
		}
	}

func (s) TestWithBackoffMaxDelay(t *testing.T) {
	md := DefaultBackoffConfig.MaxDelay / 2
	expected := DefaultBackoffConfig
	expected.MaxDelay = md
	testBackoffConfigSet(t, &expected, WithBackoffMaxDelay(md))
}

func testBackoffConfigSet(t *testing.T, expected *BackoffConfig, opts ...DialOption) {
	opts = append(opts, WithInsecure())
	conn, err := Dial("passthrough:///foo:80", opts...)
	if err != nil {
		t.Fatalf("unexpected error dialing connection: %v", err)
	}
	defer conn.Close()

	if conn.dopts.bs == nil {
		t.Fatalf("backoff config not set")
	}

	actual, ok := conn.dopts.bs.(backoff.Exponential)
	if !ok {
		t.Fatalf("unexpected type of backoff config: %#v", conn.dopts.bs)
	}

	expectedValue := backoff.Exponential{
		BaseDelay:  expected.BaseDelay,
		Multiplier: expected.Multiplier,
		Jitter:     expected.Jitter,
		MaxDelay:   expected.MaxDelay,
	}
	if actual != expectedValue {
		t.Fatalf("unexpected backoff config on connection: %v, want %v", actual, expected)
	}

	expectedMinConnectTimeout := expected.MinConnectTimeout
	if expectedMinConnectTimeout <= 0 {
		expectedMinConnectTimeout = DefaultBackoffConfig.MinConnectTimeout
	}
	if got := conn.dopts.minConnectTimeout(); got != expectedMinConnectTimeout {
		t.Fatalf("unexpected minimum connect timeout: %v, want %v", got, expectedMinConnectTimeout)
	}
}

func (s) TestWithBackoffConfig(t *testing.T) {
	partial := BackoffConfig{MaxDelay: DefaultBackoffConfig.MaxDelay / 2}
	testBackoffConfigSet(t, &partial, WithBackoffConfig(partial))

	config := BackoffConfig{
		BaseDelay:        500 * time.Millisecond,
		Multiplier:       1.2,
		Jitter:            0.1,
		MaxDelay:         DefaultBackoffConfig.MaxDelay / 2,
		MinConnectTimeout: 5 * time.Second,
	}
	testBackoffConfigSet(t, &config, WithBackoffConfig(config))
